<?php use function KB\{e,url}; use KB\Security; ?><section class="page-heading"><div><span class="eyebrow">KEEP EVERYONE IN THE LOOP</span><h1>A reliable connection.</h1><p>Deliver account confirmations, security notices and learning updates through your email provider.</p></div><a class="button secondary" href="<?= e(url('admin/notifications')) ?>">View notification queue →</a></section><?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?><form method="post" class="stack"><input type="hidden" name="smtp_enabled" value="0"><?= Security::csrfField() ?><section class="panel"><h2>SMTP connection</h2><label class="check-label"><input type="checkbox" name="smtp_enabled" value="1" <?= $settings['smtp_enabled']?'checked':'' ?>> Enable SMTP delivery</label><div class="form-grid"><label>SMTP host<input name="smtp_host" placeholder="smtp.your-provider.com" value="<?= e($settings['smtp_host']) ?>"></label><label>Port<input name="smtp_port" type="number" min="1" max="65535" value="<?= (int)$settings['smtp_port'] ?>" required></label></div><div class="form-grid"><label>Connection security<select name="smtp_security"><option value="tls" <?= $settings['smtp_security']==='tls'?'selected':'' ?>>STARTTLS (usually port 587)</option><option value="ssl" <?= $settings['smtp_security']==='ssl'?'selected':'' ?>>Implicit TLS (usually port 465)</option><?php if(KB\config('local_preview',false)): ?><option value="none" <?= $settings['smtp_security']==='none'?'selected':'' ?>>Local sandbox only — no encryption</option><?php endif; ?></select></label><label>SMTP username<input name="smtp_username" autocomplete="off" value="<?= e($settings['smtp_username']) ?>"></label></div><label>SMTP password / app password<input name="smtp_password" type="password" autocomplete="new-password" placeholder="<?= $settings['smtp_secret']?'Saved securely — leave blank to keep':'Enter your app password' ?>"><small>Encrypted at rest. Never sent to the browser.</small></label></section><section class="panel"><h2>Sender identity</h2><div class="form-grid"><label>From name<input name="from_name" maxlength="120" value="<?= e($settings['from_name']) ?>" required></label><label>From email<input name="from_email" type="email" value="<?= e($settings['from_email']) ?>"></label></div><div class="notice info">Use a sender address on your own domain. Configure SPF, DKIM and DMARC with your email provider for reliable delivery.</div></section><div class="form-actions"><button class="button">Save email settings</button><a class="text-link" href="<?= e(url('admin/notifications')) ?>">Save first, then send a test →</a></div></form>
